// Spec 601 · the low corner of the orchard, an original illustration. Story art, not a model:
// it shows what the orchard keeper sees, and claims nothing about how water moves or how much.
// Rain falls, the puddle shimmers and the reeds rise; reduced motion shows the finished picture.
const reed=(x,h,lean,delay)=>`<g class="a4c-reed" style="--d:${delay}s"><path d="M${x} 262 Q${x+lean*0.4} ${262-h*0.55} ${x+lean} ${262-h}" stroke="#5f7d3f" stroke-width="3" fill="none" stroke-linecap="round"/><path d="M${x+lean} ${262-h} q${lean>0?4:-4} -9 ${lean>0?2:-2} -22" stroke="#7a5a32" stroke-width="5" fill="none" stroke-linecap="round"/><path d="M${x+lean*0.3} ${262-h*0.35} q${lean>0?14:-14} -6 ${lean>0?24:-24} -2" stroke="#6f8d4a" stroke-width="2.5" fill="none" stroke-linecap="round"/></g>`;
const tree=(x,scale,apples)=>`<g transform="translate(${x} 0)"><path d="M0 268 C-3 230 -2 200 4 178 M4 196 C-14 186 -24 176 -30 164 M4 190 C20 182 30 170 34 158" stroke="#6b4a2f" stroke-width="${7*scale}" fill="none" stroke-linecap="round"/><ellipse cx="2" cy="${150-10*scale}" rx="${46*scale}" ry="${34*scale}" fill="#4f7a45"/><ellipse cx="-18" cy="${160-8*scale}" rx="${26*scale}" ry="${20*scale}" fill="#5c8a4f"/><ellipse cx="24" cy="${158-8*scale}" rx="${24*scale}" ry="${18*scale}" fill="#5c8a4f"/>${apples.map(([ax,ay])=>`<circle cx="${ax}" cy="${ay}" r="4.5" fill="#c4473a"/>`).join('')}</g>`;
// Smaller, paler trees up the slope: the rest of the orchard, on higher and drier ground.
const far=(x,y,s)=>`<g opacity=".85"><path d="M${x} ${y} v${-22*s}" stroke="#7a5d40" stroke-width="${3*s}" stroke-linecap="round"/><ellipse cx="${x}" cy="${y-30*s}" rx="${20*s}" ry="${15*s}" fill="#7a9a63"/><circle cx="${x-6*s}" cy="${y-32*s}" r="${2.4*s}" fill="#c4473a"/><circle cx="${x+7*s}" cy="${y-27*s}" r="${2.4*s}" fill="#c4473a"/></g>`;
const orchard=[[60,192,.8],[130,188,.85],[200,192,.8],[268,198,.9],[95,206,.95],[170,204,1],[240,210,1]].map(([x,y,s])=>far(x,y,s)).join('');
const drops=Array.from({length:26},(_,i)=>{const x=18+((i*97)%604),y=((i*53)%120),d=(i%7)*0.23;return `<path class="a4c-drop" style="--d:${d}s" d="M${x} ${y} l-4 14" stroke="#7fb3cc" stroke-width="2" stroke-linecap="round"/>`;}).join('');

export function cornerScene(label,caption){
 const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 return `<figure class="a4-corner" data-a4-corner><svg viewBox="0 0 640 300" role="img" aria-label="${esc(label)}"><defs><linearGradient id="a4c-sky" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#c9d6dc"/><stop offset="1" stop-color="#e8ede6"/></linearGradient><linearGradient id="a4c-water" x1="0" y1="0" x2="1" y2="0"><stop offset="0" stop-color="#8fb9c9"/><stop offset=".5" stop-color="#b5d4de"/><stop offset="1" stop-color="#8fb9c9"/></linearGradient></defs><rect width="640" height="300" fill="url(#a4c-sky)"/><path d="M0 196 C160 186 300 204 420 226 C500 240 580 250 640 252 V300 H0Z" fill="#9db27a"/><path d="M0 214 C150 206 300 224 430 246 C520 258 600 264 640 266 V300 H0Z" fill="#8aa268"/>${orchard}<g class="a4c-rain">${drops}</g><ellipse class="a4c-puddle" cx="470" cy="270" rx="150" ry="17" fill="url(#a4c-water)"/><path class="a4c-glint" d="M400 268 h40 M482 273 h30 M548 266 h22" stroke="#e6f1f4" stroke-width="2" stroke-linecap="round"/>${tree(380,1,[[ -20,140],[10,128],[28,150]])}${tree(470,1.15,[[-24,134],[6,122],[30,140],[-6,150]])}${tree(560,0.95,[[-16,140],[16,132]])}${reed(415,52,-6,0)}${reed(428,66,5,.25)}${reed(512,58,-4,.5)}${reed(526,74,7,.75)}${reed(538,48,-3,1)}${reed(598,62,6,1.25)}${reed(610,44,-5,1.5)}<path d="M0 214 C150 206 300 224 430 246" stroke="#7f9660" stroke-width="2" fill="none" opacity=".6"/></svg><figcaption>${esc(caption)}</figcaption></figure>`;
}
